import{z as n,x as s,o as E,c as p,q as t,j as i,D as e,d as l,s as o,S as A,b as B}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"闲暇-消费选择与劳动供给","description":"","frontmatter":{"title":"闲暇-消费选择与劳动供给","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/labor-leisure-choice.md","filePath":"econ/labor-leisure-choice.md","lastUpdated":1791063341000}'),c={name:"econ/labor-leisure-choice.md"};function d(h,a,m,T,f,u){const r=s("Mermaid");return E(),p("div",null,[a[2]||(a[2]=t('<h1 id="闲暇-消费选择与劳动供给" tabindex="-1">闲暇-消费选择与劳动供给 <a class="header-anchor" href="#闲暇-消费选择与劳动供给" aria-label="Permalink to &quot;闲暇-消费选择与劳动供给&quot;">​</a></h1><div class="epigraph"><p>工资不是「工作的报酬」，而是闲暇的价格；劳动供给从时间禀赋的配置问题里长出来。</p><footer>—— 据 Robbins, On the Elasticity of Demand for Income in Terms of Effort, Economica, 1930；Becker, A Theory of the Allocation of Time, RESTAT, 1965 整理</footer></div><p><a href="/econ/dollar-swap-lines">上一课</a>把互换线收在开放宏观续末：互换线是美联储对同行的国际最后贷款人，浮动不取消美元批发依赖，储备是自我保险、互换是弹性的中央保险。那条线到此收束。本课是「劳动经济学」的第一课。整门课要回答的是劳动市场怎么定价、谁赚得多、价格没出清时人去哪。微观课的<a href="/econ/labor-leisure">劳动–闲暇</a>已经把预算恒等式与<a href="/econ/slutsky-equation">斯勒茨基分解</a>钉过；本课不再重推，而是把那个模型重新读成劳动供给本身，钉三件事：无差异曲线与预算约束怎么定工时、工资上涨的两条效应、向后弯的供给曲线从哪来。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>时间买不来，只能分掉。每人有禀赋 \\(T\\) 小时，分成劳动 \\(h\\) 与闲暇 \\(\\ell\\)，\\(h+\\ell=T\\)；消费 \\(c\\) 由工资 \\(w\\) 与非劳动收入 \\(m\\) 支付。缺口是：给定偏好与这套预算，劳动供给几个小时、什么条件下向上、什么条件下向回弯。不把这个决定问题立起来，下一课谈「供给弹性」就没有对象。</p><p>预算约束把闲暇定价：</p> \\[c = w(T-\\ell) + m = wT + m - w\\ell . \\]<p>右端 \\(wT+m\\) 是全收入：把全部时间按工资折成钱。闲暇的价格正是 \\(w\\)——多歇一小时，放弃的是按 \\(w\\) 计价的消费，而不是抽象的「工作机会」。</p><p><span class="marginnote">术语翻译：「全收入」就是把你全部的时间按工资折成钱：\\(wT+m\\)。可以想象成每天醒来账上自动到账「24 小时 × 时薪」——之后每小时休息都是花自己的钱买闲暇。不工作的人也在「花」，只是花的是时间而不是钞票。</span></p><h3 id="供给曲线是需求曲线的镜像" tabindex="-1">供给曲线是需求曲线的镜像 <a class="header-anchor" href="#供给曲线是需求曲线的镜像" aria-label="Permalink to &quot;供给曲线是需求曲线的镜像&quot;">​</a></h3><p>劳动供给 \\(h(w,m)=T-\\ell(w,m)\\) 不是另起的一套「工作理论」，而是闲暇需求的反面。微观课的结论直接搬来：闲暇是正常品还是低档品决定收入效应的方向，替代效应永远把人从闲暇推向劳动。两者相加没有先验符号——这是本课最重要的否定结论。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>几何上在 \\((\\ell,c)\\) 平面画：预算线从禀赋点 \\((T,\\,wT+m)\\) 向左下走，斜率 \\(-w\\)；无差异曲线凸向原点；切点定最优闲暇 \\(\\ell^\\ast\\)。工资上涨让预算线绕禀赋点变陡，总变化用斯勒茨基分解拆开。对闲暇（价格 \\(w\\)、带禀赋）有：</p> \\[\\frac{\\partial h}{\\partial w} = -\\frac{\\partial \\ell^H}{\\partial w} \\;-\\; h\\,\\frac{\\partial \\ell}{\\partial m}. \\]<p>替代项 \\(-\\partial \\ell^H/\\partial w \\gt 0\\)：补偿之后闲暇变贵，少歇多干。收入项 \\(-h\\,\\partial\\ell/\\partial m\\) 在闲暇为正常品时为负：全收入升高，买回闲暇。净效应取决于两条的相对大小。</p>',15)),(E(),i(A,null,{default:e(()=>[o(r,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%B7%A5%E8%B5%84%20w%20%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20SUB%5B%22%E6%9B%BF%E4%BB%A3%E6%95%88%E5%BA%94%EF%BC%9A%E9%97%B2%E6%9A%87%E5%8F%98%E8%B4%B5%EF%BC%8C%E5%A4%9A%E5%B7%A5%E4%BD%9C%22%5D%0A%20%20W%20--%3E%20INC%5B%22%E6%94%B6%E5%85%A5%E6%95%88%E5%BA%94%EF%BC%9A%E5%85%A8%E6%94%B6%E5%85%A5%E5%8D%87%E9%AB%98%EF%BC%8C%E5%A4%9A%E9%97%B2%E6%9A%87%22%5D%0A%20%20SUB%20--%3E%20NET%5B%22%E5%87%80%E6%95%88%E5%BA%94%E6%97%A0%E5%85%88%E9%AA%8C%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20INC%20--%3E%20NET%0A%20%20NET%20--%3E%20BB%5B%22%E6%94%B6%E5%85%A5%E6%95%88%E5%BA%94%E5%8D%A0%E4%BC%98%20%E2%86%92%20%E4%BE%9B%E7%BB%99%E5%90%91%E5%90%8E%E5%BC%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[l("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"收入效应压过替代效应时，\\(\\partial h/\\partial w \\lt 0\\)：工资越高反而干得越少，供给曲线在高工资段向后弯。这不是悖论，与吉芬品同构——闲暇是正常品，而且在「消费篮子」里占比极大：每人每天只有有限小时，闲暇几乎是最大的消费品。历史形态与此一致：实际工资长期上涨伴着周工时长期下降。反过来，工资在低位时收入效应弱（全收入的基数小）、替代效应主导，曲线前段向上。一条完整的个人供给曲线因此先是上倾、后段回弯。",-1)),(E(),i(A,null,{default:e(()=>[o(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOW%5B%22%E4%BD%8E%E5%B7%A5%E8%B5%84%E6%AE%B5%22%5D%20--%3E%20WEAK%5B%22%E5%85%A8%E6%94%B6%E5%85%A5%E5%9F%BA%E6%95%B0%E5%B0%8F%3A%20%E6%94%B6%E5%85%A5%E6%95%88%E5%BA%94%E5%BC%B1%22%5D%0A%20%20WEAK%20--%3E%20UP%5B%22%E6%9B%BF%E4%BB%A3%E6%95%88%E5%BA%94%E4%B8%BB%E5%AF%BC%3A%20%E4%BE%9B%E7%BB%99%E5%90%91%E4%B8%8A%22%5D%0A%20%20HIGH%5B%22%E9%AB%98%E5%B7%A5%E8%B5%84%E6%AE%B5%22%5D%20--%3E%20STRONG%5B%22%E9%97%B2%E6%9A%87%E5%8D%A0%E7%AF%AE%E5%AD%90%E5%A4%A7%3A%20%E6%94%B6%E5%85%A5%E6%95%88%E5%BA%94%E5%BC%BA%22%5D%0A%20%20STRONG%20--%3E%20BACK%5B%22%E6%94%B6%E5%85%A5%E6%95%88%E5%BA%94%E5%8D%A0%E4%BC%98%3A%20%E4%BE%9B%E7%BB%99%E5%9B%9E%E5%BC%AF%22%5D%0A%20%20UP%20--%3E%20SHAPE%5B%22%E4%B8%AA%E4%BA%BA%E4%BE%9B%E7%BB%99%E6%9B%B2%E7%BA%BF%3A%20%E5%85%88%E4%B8%8A%E5%80%BE%E5%90%8E%E5%9B%9E%E5%BC%AF%22%5D%0A%20%20BACK%20--%3E%20SHAPE%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">数字实例：时薪 50 元时，多歇 1 小时等于放弃 50 元消费；时薪涨到 100 元，同样 1 小时闲暇的「标价」翻倍——替代效应催你少歇。但全收入也从每天 1200 元涨到 2400 元，有钱买得起更多闲暇——收入效应劝你多歇。谁赢没有先验答案，这正是净效应符号不定的算术来源。</span></p><p><span class="marginnote">全收入口径里，不工作的人也在「花」自己的时间：禀赋点把 \\(T\\) 小时按 \\(w\\) 折成钱，闲暇是买回自己。角点 \\(\\ell=T\\)（完全不工作）上不存在切点——参与与否比较的是保留工资与市场工资，这正是下一课的门。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只处理内点的连续选择：假设每小时都可调。现实有制度工时（八小时、全职与兼职）、固定工作成本（通勤、执照），参与决策因此是离散的——下一课的参与边际。模型里也没有税收：所得税楔在 \\(w\\) 与净工资之间，替代与收入效应都要在净价上重算，<a href="/econ/income-tax-incentives">所得税与激励</a>是那边的口径。更不要把「勤奋」当性格变量塞进偏好：模型里人只偏好消费与闲暇的组合，跨人差异落在无差异曲线的形状上，那正是下一课要估的异质性。</p><p><span class="marginnote">常见误区：把向后弯的供给曲线读成「人变懒了」。它是价格效应的算术结果：闲暇是正常品、又在时间禀赋里占比极大，高工资段收入效应自然压过替代效应。历史上实际工资长期上涨伴随周工时长期下降，正是这条曲线的宏观影子——变的是价格，不是性格。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>劳动供给是闲暇需求的镜像：\\(h=T-\\ell\\)，闲暇的价格是工资。</li><li>替代效应推劳动上升，收入效应（闲暇正常时）拉回；净效应没有先验符号。</li><li>向后弯不是悖论，是收入效应占优，与吉芬品同构。</li><li>本课只处理内点连续选择；参与、税收与工时约束是下一课的缺口。</li><li>出处：Robbins 1930；Becker 1965；微观课劳动–闲暇与斯勒茨基分解的先行处理。</li></ul>',7))])}const b=n(c,[["render",d]]);export{D as __pageData,b as default};
